test_cases.assertion_script:
const display = await page.$eval('.card', el => getComputedStyle(el).display);
assert.strictEqual(display, 'flex');
const justify = await page.$eval('.card', el => getComputedStyle(el).justifyContent);
assert.strictEqual(justify, 'space-between');

const box = await page.$eval('.card', el => { const r = el.getBoundingClientRect(); const label = el.querySelector('.label').getBoundingClientRect(); const value = el.querySelector('.value').getBoundingClientRect(); return { sameRow: Math.abs(label.top - value.top) < 2, labelBeforeValue: label.left < value.left }; });
assert.ok(box.sameRow, '.label and .value should be on the same row');
assert.ok(box.labelBeforeValue, '.label should be left of .value');
